<script setup lang="ts">
import {ref} from 'vue';
import type {Configuration,TankGroup,MediumDefinition} from './api';
const props=defineProps<{config:Configuration;admin:boolean;mode:string}>(),emit=defineEmits<{dirty:[]}>();
const group=ref<TankGroup|null>(null),medium=ref<MediumDefinition|null>(null),error=ref('');
const kinds:Record<string,string>={Zone:'罐区',TankGroup:'罐组',Medium:'介质',Batch:'设备批次'};
const copy=<T,>(x:T):T=>JSON.parse(JSON.stringify(x));
function addGroup(){group.value={id:crypto.randomUUID(),name:'',kind:'Zone',parentId:null,tankIds:[]};error.value=''}
function parents(id:string){const blocked=new Set([id]);let change=true;while(change){change=false;for(const g of props.config.groups)if(g.parentId&&blocked.has(g.parentId)&&!blocked.has(g.id)){blocked.add(g.id);change=true}}return props.config.groups.filter(g=>!blocked.has(g.id))}
function applyGroup(){const d=group.value;if(!d)return;d.name=d.name.trim();if(!d.name){error.value='请填写分组名称';return}const i=props.config.groups.findIndex(x=>x.id===d.id);if(i<0)props.config.groups.push(copy(d));else props.config.groups[i]=copy(d);group.value=null;emit('dirty')}
function removeGroup(g:TankGroup){if(!confirm('删除分组 '+g.name+'？储罐及历史保留，下级分组移到其上级。'))return;props.config.groups.splice(0,props.config.groups.length,...props.config.groups.filter(x=>x.id!==g.id).map(x=>x.parentId===g.id?{...x,parentId:g.parentId}:x));emit('dirty')}
function addMedium(){medium.value={id:crypto.randomUUID(),code:'',name:'',category:'',color:'#659da0',referenceTemperatureC:null,standardDensityKgM3:null};error.value=''}
function applyMedium(){const d=medium.value;if(!d)return;d.name=d.name.trim();d.code=d.code.trim();if(typeof d.referenceTemperatureC!=='number')d.referenceTemperatureC=null;if(typeof d.standardDensityKgM3!=='number')d.standardDensityKgM3=null;if(!d.name||!d.code){error.value='请填写介质编号及名称';return}const i=props.config.media.findIndex(x=>x.id===d.id);if(i<0)props.config.media.push(copy(d));else props.config.media[i]=copy(d);for(const t of props.config.tanks)if(t.mediumId===d.id)t.medium=d.name;medium.value=null;emit('dirty')}
function removeMedium(m:MediumDefinition){if(props.config.tanks.some(t=>t.mediumId===m.id)){error.value='此介质仍有关联储罐，请先更换储罐的介质';return}if(confirm('删除介质 '+m.name+'？')){props.config.media.splice(props.config.media.findIndex(x=>x.id===m.id),1);emit('dirty')}}
</script>
<template>
 <template v-if="mode==='groups'"><div class="toolbar"><span>分组用于筛选和汇总，可包含下级分组；删除分组保留储罐及记录。</span><button v-if="admin" class="button primary" @click="addGroup">新增分组</button></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>名称</th><th>类型</th><th>上级分组</th><th>直接关联储罐</th><th>操作</th></tr></thead><tbody><tr v-for="g in config.groups" :key="g.id"><td>{{g.name}}</td><td>{{kinds[g.kind]}}</td><td>{{config.groups.find(x=>x.id===g.parentId)?.name||'无上级'}}</td><td class="table-associations">{{g.tankIds.map(id=>config.tanks.find(t=>t.id===id)?.code).join('、')||'—'}}</td><td><button v-if="admin" class="text-button" @click="group=copy(g);error=''">编辑</button><button v-if="admin" class="text-button" @click="removeGroup(g)">删除</button></td></tr><tr v-if="!config.groups.length"><td colspan="5" class="empty">尚未配置分组</td></tr></tbody></table></div></section></template>
 <template v-if="mode==='media'"><div class="toolbar"><span>介质颜色仅用于名称标签；标准密度资料不替代仪表实测密度。</span><button v-if="admin" class="button primary" @click="addMedium">新增介质</button></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>编号</th><th>名称</th><th>类别</th><th>参考温度 ℃</th><th>标准密度 kg/m³</th><th>操作</th></tr></thead><tbody><tr v-for="m in config.media" :key="m.id"><td>{{m.code}}</td><td><span class="medium-chip" :style="{borderColor:m.color,color:m.color}">{{m.name}}</span></td><td>{{m.category||'—'}}</td><td>{{m.referenceTemperatureC??'—'}}</td><td>{{m.standardDensityKgM3??'—'}}</td><td><button v-if="admin" class="text-button" @click="medium=copy(m);error=''">编辑</button><button v-if="admin" class="text-button" @click="removeMedium(m)">删除</button></td></tr><tr v-if="!config.media.length"><td colspan="6" class="empty">尚未配置介质</td></tr></tbody></table></div></section></template>
 <section v-if="mode==='units'" class="panel panel-body"><h2>显示单位与精度</h2><div class="config-fields" @change="emit('dirty')"><label class="config-field">液位单位<select v-model="config.display.heightUnit" aria-label="液位单位" :disabled="!admin"><option value="Millimetre">mm</option><option value="Centimetre">cm</option><option value="Metre">m</option></select></label><label class="config-field">体积单位<select v-model="config.display.volumeUnit" aria-label="体积单位" :disabled="!admin"><option value="CubicMetre">m³</option><option value="Litre">L</option></select></label><label class="config-field">密度单位<select v-model="config.display.densityUnit" aria-label="密度单位" :disabled="!admin"><option value="KilogramPerCubicMetre">kg/m³</option><option value="GramPerCubicCentimetre">g/cm³</option></select></label><label class="config-field">质量单位<select v-model="config.display.massUnit" aria-label="质量单位" :disabled="!admin"><option value="Tonne">t</option><option value="Kilogram">kg</option></select></label><label class="config-field">体积小数位<input v-model.number="config.display.volumeDecimals" type="number" min="0" max="6" :disabled="!admin"></label><label class="config-field">质量小数位<input v-model.number="config.display.massDecimals" type="number" min="0" max="6" :disabled="!admin"></label></div><label class="config-field">页面刷新间隔（秒）<input v-model.number="config.display.refreshIntervalSeconds" type="number" min="1" max="30" :disabled="!admin" aria-label="页面刷新间隔（秒）" @change="emit('dirty')"></label><p class="help">页面每1～30秒刷新，与通道采集周期、历史保存周期分别设置。显示、查询和导出采用相同单位。改变显示单位不改变原始数据、报警阈值或罐容表录入单位。</p></section>
 <p v-if="error&&!group&&!medium" role="alert" class="error-message">{{error}}</p>
 <div v-if="group||medium" class="modal-backdrop"><section class="modal" role="dialog"><div class="modal-head"><h2>{{group?'分组配置':'介质配置'}}</h2><button class="button" @click="group=null;medium=null">关闭</button></div><div class="modal-body"><p v-if="error" class="error-message">{{error}}</p><form v-if="group" @submit.prevent="applyGroup"><div class="config-fields"><label class="config-field">分组名称<input v-model="group.name" required maxlength="100"></label><label class="config-field">分组类型<select v-model="group.kind" aria-label="分组类型"><option v-for="(n,k) in kinds" :key="k" :value="k">{{n}}</option></select></label><label class="config-field">上级分组<select v-model="group.parentId" aria-label="上级分组"><option :value="null">无上级</option><option v-for="g in parents(group.id)" :key="g.id" :value="g.id">{{g.name}}</option></select></label></div><h3>分配储罐</h3><div class="bulk-tanks"><label v-for="t in config.tanks" :key="t.id" class="checkbox"><input v-model="group.tankIds" type="checkbox" :value="t.id">{{t.code}}</label></div><button class="button primary">应用到待保存配置</button></form><form v-if="medium" class="config-fields" @submit.prevent="applyMedium"><label class="config-field">介质编号<input v-model="medium.code" required maxlength="80"></label><label class="config-field">介质名称<input v-model="medium.name" required maxlength="100"></label><label class="config-field">介质类别（选填）<input v-model="medium.category" maxlength="100"></label><label class="config-field">标签颜色<input v-model="medium.color" type="color"></label><label class="config-field">参考温度 ℃<input v-model.number="medium.referenceTemperatureC" type="number" step="any"></label><label class="config-field">标准密度 kg/m³<input v-model.number="medium.standardDensityKgM3" type="number" min="0.001" step="any"></label><button class="button primary wide-field">应用到待保存配置</button></form></div></section></div>
</template>
